--

CREATE TABLE `factures_forfaits` (
  `id` int NOT NULL,
  `numero_facture` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Numéro unique de facture (ex: INV-2025-001)',
  `user_id` int NOT NULL COMMENT 'ID de l''utilisateur',
