  `date_expiration` datetime DEFAULT NULL COMMENT 'Date de fin du forfait (NULL = illimité)',
  `duree_mois` int DEFAULT NULL COMMENT 'Durée en mois du forfait',
  `statut` enum('payee','impayee','annulee') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'payee',
