--
-- Structure de la table `forfaits`
--

CREATE TABLE `forfaits` (
  `id` int NOT NULL,
  `nom` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nom du forfait (ex: Gratuit, Premium, Business)',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Description détaillée du forfait',
  `prix_mensuel` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'Prix par mois en euros',
  `prix_annuel` decimal(10,2) DEFAULT NULL COMMENT 'Prix par an en euros (réduction possible)',
  `type_facturation` enum('unique','mensuelle','annuelle') COLLATE utf8mb4_unicode_ci DEFAULT 'unique',
  `duree_abonnement_mois` int DEFAULT NULL,
  `duree_offre_jours` int DEFAULT NULL,
  `logo_page_accueil` tinyint(1) DEFAULT '0',
  `gestion_candidatures` tinyint(1) DEFAULT '0',
  `duree` enum('mensuel','trimestriel','semestriel','annuel') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'mensuel',
  `max_missions` int DEFAULT NULL COMMENT 'Nombre max de missions postées/postulations (NULL = illimité)',
  `max_documents` int DEFAULT NULL COMMENT 'Nombre max de documents uploadés (NULL = illimité)',
  `priorite_support` enum('standard','prioritaire','premium') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'standard',
  `badge_premium` tinyint(1) DEFAULT '0' COMMENT 'Badge premium visible sur le profil',
  `mise_en_avant` tinyint(1) DEFAULT '0' COMMENT 'Profil mis en avant dans les recherches',
  `statistiques_avancees` tinyint(1) DEFAULT '0' COMMENT 'Accès aux statistiques avancées',
  `api_access` tinyint(1) DEFAULT '0' COMMENT 'Accès à l''API',
  `peut_publier_missions` tinyint(1) DEFAULT '0',
  `label_indebel` tinyint(1) DEFAULT '0',
  `type_utilisateur` enum('freelancer','employer','les_deux') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'les_deux' COMMENT 'À qui s''adresse ce forfait',
  `actif` tinyint(1) DEFAULT '1' COMMENT 'Forfait actif et visible',
  `recommande` tinyint(1) DEFAULT '0' COMMENT 'Forfait recommandé (affiché en évidence)',
  `couleur_badge` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '#6B7280' COMMENT 'Couleur hexadécimale du badge',
  `date_creation` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `date_modification` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `max_postulations` int DEFAULT NULL,
  `max_devis` int DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

