  `accepte_emails` tinyint(1) DEFAULT '0',
  `derniere_connexion` timestamp NULL DEFAULT NULL,
  `experience` int DEFAULT NULL,
  `tarif_journalier` decimal(10,2) DEFAULT NULL,
  `disponibilite` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `portfolio_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `denomination` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description_entreprise` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `a_propos` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `site_web` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `taille_entreprise` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `poste` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `verification_statut` enum('non_verifie','en_attente','verifie','refuse') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'non_verifie',
  `verification_document_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `verification_document_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `verification_document_recto_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `verification_document_verso_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `verification_selfie_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `verification_date_soumission` timestamp NULL DEFAULT NULL,
  `verification_date_validation` timestamp NULL DEFAULT NULL,
  `verification_admin_id` int DEFAULT NULL,
  `verification_commentaire` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `photo_profil` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `image_couverture` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `last_login` timestamp NULL DEFAULT NULL COMMENT 'Date de dernière connexion',
  `genre` enum('homme','femme','autre','non_specifie') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'non_specifie',
  `tranche_age` enum('18-25','26-35','36-45','46-55','56+') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `statut_verification` enum('non_verifie','en_cours','verifie','refuse') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'non_verifie',
  `disponibilite_debut` date DEFAULT NULL,
  `disponibilite_fin` date DEFAULT NULL,
  `forfait_id` int DEFAULT NULL COMMENT 'Forfait actuel de l''utilisateur',
  `forfait_date_souscription` timestamp NULL DEFAULT NULL,
  `forfait_date_expiration` timestamp NULL DEFAULT NULL,
  `notified_7days` tinyint(1) DEFAULT '0',
  `notified_expiration` tinyint(1) DEFAULT '0',
  `forfait_date_debut` date DEFAULT NULL COMMENT 'Date de début du forfait',
  `forfait_date_fin` date DEFAULT NULL COMMENT 'Date de fin du forfait (NULL = illimité)',
  `forfait_statut` enum('actif','expire','annule') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'actif',
  `facebook` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `instagram` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `linkedin` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `twitter` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email_contact` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `annee_creation` int DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

