--
-- Structure de la table `verifications_identite`
--

CREATE TABLE `verifications_identite` (
  `id` int NOT NULL,
  `freelancer_id` int NOT NULL,
  `nom_complet` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_naissance` date NOT NULL,
  `adresse_complete` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `telephone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `type_document` enum('carte_identite','passeport','permis_conduire','titre_sejour') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `numero_document` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `document_recto` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Base64 ou URL du document recto',
  `document_verso` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Base64 ou URL du document verso',
  `selfie_document` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Base64 ou URL du selfie avec document',
  `statut` enum('en_attente','valide','refuse') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'en_attente',
  `motif_refus` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Raison du refus si statut refuse',
  `date_soumission` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `date_traitement` timestamp NULL DEFAULT NULL,
  `traite_par` int DEFAULT NULL COMMENT 'ID admin qui a traité',
  `assurance_rc_professionnelle` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Base64 assurance RC pro',
  `justificatif_domicile` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Base64 justificatif domicile',
  `extrait_bce` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Base64 extrait BCE',
  `attestation_cotisations_sociales` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Base64 attestation cotisations',
  `a_permis_conduire` tinyint(1) DEFAULT '0' COMMENT 'Possède un permis de conduire',
  `categorie_permis_conduire` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Catégorie du permis (B, C, D, etc.)',
  `document_permis_conduire` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Base64 document permis',
  `a_permis_chariot` tinyint(1) DEFAULT '0' COMMENT 'Possède un permis chariot',
  `nombre_permis_chariot` int DEFAULT '0' COMMENT 'Nombre de permis chariot',
  `document_permis_chariot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Base64 document permis chariot'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

